message.content:
{
"css": ".mentor-body {
  font-size: 14px;
  line-height: 22px;
  font-weight: 500;
  color: var(--muted);
}

.mentor-role {
  margin: 0;
}

.mentor-description {
  margin-top: 4px;
}

.mentor-footer {
  margin-top: 14px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.mentor-footer button {
  padding: 2px 6px;
  border-radius: 6px;
  font-size: 14px;
  line-height: 1.57;
  font-weight: 500;
  background-color: #f0f2f5;
  color: var(--muted);
  border: none;
  cursor: default;
  white-space: nowrap;
}"
}
